														local v7 = if v6 then v6:FindFirstChild("EquippedTrinket1") else v6
														local v8 = if v6 then v6:FindFirstChild("EquippedTrinket2") else v6
														local v9 = if v7 and v7.Value == v1 then true elseif v8 then if v8.Value == v1 then true else false else v8
														local v10 = nil

														for k, v in pairs(v5:GetDescendants()) do
															if v:IsA("TextLabel") then
																v10 = v

																break
															end
														end

														if not v10 and v5:IsA("TextButton") then
															v10 = v5
														end

														if not v10 then
															Dropdown.Visible = false

															return
														end

														v10.Text = if v9 then "Unequip" else "Equip"
														Dropdown.Visible = false
													else
														if not GameContext.ErrorMessage then
															return
														end

														GameContext.ErrorMessage("Failed to equip loadout " .. i)
													end
												end)
											end
										end
									end
								end
							end
						end

						task.wait(0.1)
						v12 = false
					end)
				end
			end
		end
	end

	if not BottomFrame or v1.readyUpButton then
		return
	end

	local ReadyStatus = BottomFrame:FindFirstChild("ReadyStatus")

	if not ReadyStatus then
		return
	end

	v1.readyUpButton = ReadyStatus:FindFirstChild("ReadyUp")
	v1.roundTimer = ReadyStatus:FindFirstChild("GameStarting")
end

return t